sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }

    var joiningDate = g_form.getValue('joining_date');
    joiningDate = new Date(joiningDate + 'T00:00:00');
    var currentDate = new Date();
    currentDate.setHours(0, 0, 0, 0);

    if (joiningDate < currentDate) {

        //g_form.showFieldMsg('joining_date', 'Joining Date should be either todays date or future one!', 'error');
		g_form.addErrorMessage('Joining Date should be either todays date or future one!');
        g_form.clearValue('joining_date');
    } else {
        return true;
    }
}
